  <section class="quote-section"><div class="container"><div class="eyebrow">CULTURAL MEMORY</div><blockquote>${lang==='ru'?'«Наследие живёт, пока мы продолжаем его открывать».':'«Мұра оны танып-білген сайын өмір сүреді».'}</blockquote><a class="btn" href="index.html#quiz">${tr().quiz} ↗</a></div></section>
