function storyTiles(stories,kind){const t=heritageExtra[lang];return stories.map((s,i)=>`<article class="memory-tile"><span class="memory-index">0${i+1}</span><h3>${s[0]}</h3><button class="memory-toggle" type="button" aria-expanded="false">${t.read} <span aria-hidden="true">↗</span></button><div class="memory-reveal" hidden><p>${s[1]}</p><a href="${s[2]}" target="_blank" rel="noopener noreferrer">${t.source} ↗</a></div></article>`).join('')}
// РАХАТ — Ашаршылық и Мәңгілік алау
function memorialSections(){
 const kz=lang==='kz';
 const card=(img,head,desc,i,href)=>`<a class="scrap-photo reveal-scrap" href="${href}" style="--turn:${[-4,3,-2,4][i]}deg;--delay:${i*95}ms"><div class="scrap-image"><img src="assets/images/${img}.webp" loading="lazy" alt="${head}"></div><div class="scrap-caption"><strong>${head}</strong><span>${desc}</span><span class="scrap-arrow">↗</span></div></a>`;
 return `<div class="memory-experience" id="asharshylyk"><section class="scrap-section famine-scrap"><div class="scrap-wrap"><div class="scrap-ornament" aria-hidden="true">❧ ✦ ❧</div><div class="scrap-intro reveal-scrap"><span class="scrap-kicker">05 / ${kz?'ТАРИХ ПАРАҚТАРЫ':'СТРАНИЦЫ ИСТОРИИ'}</span><h2>${kz?'Ашаршылық':'Ашаршылық'}</h2><em>1931 — 1933</em><p>${kz?'Күштеп ұжымдастыру, малды тәркілеу және дәстүрлі шаруашылықтың күйреуі Қазақстанда жаппай ашаршылыққа әкелді. Бұл — ұмытылмауға тиіс тарихи қасірет.':'Насильственная коллективизация, изъятие скота и разрушение традиционного хозяйства привели к массовому голоду в Казахстане. Эта трагедия требует бережной памяти.'}</p><a class="scrap-button" href="asharshylyk.html">${kz?'Толық тарих':'Читать историю'} <span>→</span></a></div><div class="famine-layout"><div class="scrap-photos famine-photos">${card('famine-family',kz?'Отбасы тағдыры':'Судьбы семей',kz?'Тарихи естелік':'Историческая память',0,'asharshylyk.html#families')}${card('famine-journey',kz?'Көшу':'Переселение',kz?'Жан сақтау жолында':'В поисках спасения',1,'asharshylyk.html#migration')}${card('famine-yurt',kz?'Қаңыраған ауыл':'Опустевшие аулы',kz?'Даладағы өзгерістер':'Изменения в степи',2,'asharshylyk.html#villages')}${card('famine-grain',kz?'Астық тәркілеу':'Изъятие зерна',kz?'Ашаршылық себептері':'Причины голода',3,'asharshylyk.html#causes')}</div><article class="famine-memorial reveal-scrap"><a class="memorial-source" href="https://cbspvl.kz/projects/Pamyatniki/3-hist.pdf" target="_blank" rel="noopener"><img src="assets/images/famine-memorial.webp" alt="${kz?'Мемориалдың көркем бейнесі':'Художественная иллюстрация мемориала'}"><small>${kz?'Көркем бейне · Нақты фотосуреттер ↗':'Художественная иллюстрация · Реальные фотографии ↗'}</small></a><h3>${kz?'Ашаршылық құрбандарына ескерткіш':'Памятник жертвам голодомора'}</h3><em>${kz?'Павлодар · 31 мамыр 2012 жыл':'Павлодар · 31 мая 2012 года'}</em><p>${kz?'Ескерткіш ескі мұсылман қорымының кіреберісінде ашылды. Авторы — мүсінші Марат Абылқасымов. Мемориал ашаршылық құрбандарын еске алуға арналған.':'Мемориал открыт у входа на старое мусульманское кладбище. Автор — скульптор Марат Абылкасимов. Памятник посвящён памяти жертв голода.'}</p><a href="https://kaz.inform.kz/news/pavlodarda-asharshylyk-kurbandaryna-eskertkish-ornatyldy_a2468527/" target="_blank" rel="noopener">${kz?'Дереккөз':'Источник'} ↗</a></article></div></div><div class="paper-rip" aria-hidden="true"></div></section><section class="scrap-section flame-scrap" id="eternal-flame"><div class="scrap-wrap"><div class="flame-scrap-head reveal-scrap"><span class="scrap-kicker">06 / ${kz?'ЕРЛІККЕ ТАҒЗЫМ':'ПАМЯТЬ О ПОДВИГЕ'}</span><h2>${kz?'Мәңгілік алау':'Вечный огонь'}</h2><em>${kz?'1975 жылы ашылды':'Открыт в 1975 году'}</em><p>${kz?'Павлодардағы Мәңгілік алау соғыста қаза тапқан жауынгерлерді еске алу орны. Бұл — ұрпақтар алғысының белгісі.':'Вечный огонь в Павлодаре — место памяти о погибших в годы войны. Он символизирует благодарность и уважение поколений.'}</p><a class="scrap-button" href="mangilik-alau.html">${kz?'Толық мәлімет':'Подробнее'} <span>→</span></a></div><a href="mangilik-alau.html#memorial" class="monument-photo reveal-scrap"><img src="assets/images/flame-monument.webp" alt="Иллюстрация мемориала"><span class="flame-hover-label">${kz?'Мемориал тарихы ↗':'История мемориала ↗'}</span><span class="living-flame" aria-hidden="true">♨</span></a><div class="flame-bottom">${card('flame-ceremony',kz?'Ашылу салтанаты':'Церемония открытия','',0,'mangilik-alau.html#opening')}${card('flame-veterans',kz?'Ардагерлер':'Ветераны','',1,'mangilik-alau.html#veterans')}${card('flame-flowers',kz?'Тағзым':'Память сегодня','',2,'mangilik-alau.html#today')}<div class="scrap-names reveal-scrap"><span>✦</span><h3>${kz?'Есте сақталған есімдер':'Имена, которые помнят'}</h3><p>${kz?'Майданнан оралмаған жерлестердің есімдері ұрпақ жадында сақталады.':'Имена земляков, не вернувшихся с фронта, остаются в памяти поколений.'}</p><a href="mangilik-alau.html#names">${kz?'Естелікке өту':'Открыть истории'} ↗</a></div></div></div></section></div>`;
}
function museumArchiveSection(i){const t=heritageExtra[lang],m=museumArchives[lang][i];return `<section class="archive-section" id="archive"><div class="container"><div class="eyebrow">HISTORY · PAVLODAR</div><h2>${t.museumHistory}</h2><p class="archive-date">${m.date}</p><h3>${m.title}</h3><p class="archive-intro">${m.intro}</p><div class="archive-timeline">${m.steps.map(st=>`<article><b>${st[0]}</b><p>${st[1]}</p></article>`).join('')}</div><h2>${t.interesting}</h2><div class="archive-facts">${m.facts.map((f,j)=>`<div><span>0${j+1}</span>${f}</div>`).join('')}</div><h2>${t.galleryTitle}</h2><p>${t.galleryNote}</p><div class="archive-gallery">${m.images.map((img,j)=>`<figure><img src="assets/images/${img[0]}" alt="${img[1]}" loading="lazy"><figcaption>${img[1]}</figcaption></figure>`).join('')}</div><div class="archive-links"><a href="${m.source}" target="_blank" rel="noopener noreferrer">${t.source} 01 ↗</a><a href="${m.extra}" target="_blank" rel="noopener noreferrer">${t.source} 02 ↗</a></div></div></section>`}

function footer() {
  return `<footer class="heritage-footer"><div class="footer-pattern" aria-hidden="true">❧ ◈ ❧ ◈ ❧ ◈ ❧</div><div class="container footer-layout"><div><div class="eyebrow">PAVLODAR · CULTURAL HERITAGE</div><h3>МУЗЕЙ — ТАРИХ БЕСІГІ</h3><p>${tr().intro}</p><p class="footer-quote">Өткеннің мұрасы — болашақтың қазынасы</p></div><div class="footer-contact"><h4>${lang==='ru'?'Связаться с проектом':'Жобамен байланысу'}</h4><a href="mailto:rahatalibayandin@gmail.com">rahatalibayandin@gmail.com</a><a href="tel:+77071252664">+7 707 125 2664</a><a class="footer-up" href="index.html">↑ ${tr().back}</a></div></div><div class="container footer-bottom"><span>© 2026 · Музей — тарих бесігі</span><span>${tr().sources}</span></div></footer>`;
}
function render() {
  root.innerHTML = header() + (page==='home'?home():detail()) + footer() + `<div class="modal" id="modal" hidden><div class="modal-inner"><button class="close" id="close-modal">✕</button><img id="modal-image" alt=""><h3 id="modal-title"></h3><p id="modal-story"></p><p class="modal-note" id="modal-note"></p><div class="modal-decoration" aria-hidden="true">❧ ✦ ❧</div></div></div>`;
  document.getElementById('language').onclick=()=>{lang=lang==='ru'?'kz':'ru';try{localStorage.setItem('museum-lang',lang);}catch(_){}render();};
  document.querySelectorAll('[data-exhibit]').forEach(btn=>btn.onclick=()=>{
    const i=Number(btn.dataset.exhibit);
    document.getElementById('modal-image').src='assets/images/'+galleryDetailImages[i];
    document.getElementById('modal-image').alt=galleryStories[lang][i][0];
    document.getElementById('modal-story').textContent=galleryStories[lang][i][1];
    document.getElementById('modal-note').textContent=galleryStories[lang][i][2];
    document.getElementById('modal-title').textContent=galleryStories[lang][i][0];
    document.getElementById('modal').hidden=false;
    document.getElementById('modal').classList.remove('modal-opening');
    void document.getElementById('modal').offsetWidth;
    document.getElementById('modal').classList.add('modal-opening');
  });
  const scrapbookObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('scrap-visible');scrapbookObserver.unobserve(e.target);}}),{threshold:.12});
  document.querySelectorAll('.reveal-scrap').forEach(el=>scrapbookObserver.observe(el));
  document.querySelectorAll('.memory-toggle').forEach(btn=>btn.addEventListener('click',()=>{const pane=btn.nextElementSibling;const open=btn.getAttribute('aria-expanded')==='true';btn.setAttribute('aria-expanded',String(!open));pane.hidden=open;btn.firstChild.textContent=open?heritageExtra[lang].read+' ':heritageExtra[lang].close+' ';}));
  document.getElementById('close-modal').onclick=()=>document.getElementById('modal').hidden=true;
  document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')e.target.hidden=true;};
  if(page==='home') {
    document.querySelectorAll('[data-place]').forEach(btn=>btn.onclick=()=>showPlace(Number(btn.dataset.place)));
    showPlace(0);
    renderQuiz();
  }
  const chapterSelect=document.getElementById('chapter-select');
  if(chapterSelect){
    chapterSelect.innerHTML=(lang==='kz'?historyChaptersKz:historyChapters).map((ch,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${ch[0]}</option>`).join('');
    const displayChapter=()=>{
      const ch=(lang==='kz'?historyChaptersKz:historyChapters)[historyIndex];
      document.getElementById('book-epoch').textContent='';
      document.getElementById('book-left-heading').textContent=ch[3];
      const sentences=ch[2].match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[ch[2]];
      const splitAt=Math.max(1,Math.ceil(sentences.length/2));
      document.getElementById('book-left-copy').textContent=sentences.slice(0,splitAt).join(' ').trim();
      document.getElementById('book-counter').textContent=String(historyIndex+1).padStart(2,'0')+' / '+historyChapters.length;
      document.getElementById('book-period').textContent=ch[1];
      document.getElementById('book-chapter').textContent=ch[0];
      document.getElementById('book-content').textContent=sentences.slice(splitAt).join(' ').trim()||ch[2];
      document.getElementById('book-progress').textContent=String(historyIndex+1).padStart(2,'0')+' / '+historyChapters.length;
      chapterSelect.value=String(historyIndex);
      document.getElementById('book-prev').disabled=historyIndex===0;
      document.getElementById('book-next').disabled=historyIndex===historyChapters.length-1;
    };
    let turning=false;
    const goChapter=(index)=>{
      if(turning||index<0||index>=historyChapters.length||index===historyIndex)return;
      const flip=document.getElementById('page-flip');
      const book=document.getElementById('heritage-book');
      if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){historyIndex=index;displayChapter();return;}
      turning=true;
      flip.classList.remove('turning');
      book.classList.add('is-turning');
      void flip.offsetWidth;
      flip.classList.add('turning');
      window.setTimeout(()=>{historyIndex=index;displayChapter();},390);
      window.setTimeout(()=>{flip.classList.remove('turning');book.classList.remove('is-turning');turning=false;},850);
    };
    document.getElementById('book-prev').onclick=()=>goChapter(historyIndex-1);
    document.getElementById('book-next').onclick=()=>goChapter(historyIndex+1);
    chapterSelect.onchange=()=>goChapter(Number(chapterSelect.value));
    document.querySelector('#book-prev span').textContent=lang==='kz'?'Артқа':'Назад';
    document.querySelector('#book-next span').textContent=lang==='kz'?'Парақтау':'Листать';
    document.querySelector('.book-guidance').textContent=lang==='kz'?'Кітапты парақтау үшін бет бұрышын басыңыз':'Нажмите на угол страницы, чтобы перелистнуть книгу';
    document.querySelector('.chapter-label').textContent=lang==='kz'?'Тарауды таңдау':'Выбрать главу';
    document.querySelector('.book-hint').textContent=lang==='kz'?'17 тарау · Қазақстанның ежелгі дәуірден бүгінге дейінгі қысқаша тарихы':'17 глав · краткая история Казахстана от древности до наших дней';
    document.getElementById('book-prev').setAttribute('aria-label',lang==='kz'?'Алдыңғы бет':'Предыдущая страница');
    document.getElementById('book-next').setAttribute('aria-label',lang==='kz'?'Келесі бет':'Следующая страница');
    displayChapter();
  }
  addVirtualGuides();
  initArtEffects();
}
function showPlace(i) {
  const m=items[i];
  document.querySelectorAll('.map-pin').forEach((pin,n)=>{pin.classList.toggle('active',n===i);pin.setAttribute('aria-pressed',String(n===i));});
  const query=encodeURIComponent(tr().names[i]+' Павлодар Казахстан');
  const frame=document.getElementById('museum-map-frame');
  if(frame)frame.src='https://maps.google.com/maps?q='+query+'&z=16&output=embed';
  const external=document.getElementById('map-external');if(external)external.href='https://www.google.com/maps/search/?api=1&query='+query;
  document.getElementById('map-detail').innerHTML=`<img class="map-detail-image" src="assets/images/${m.image}" alt="Иллюстрация учреждения"><div><div class="eyebrow">0${i+1} / PAVLODAR</div><h3>${tr().names[i]}</h3><p>${tr().desc[i]}</p><p>${tr().mapInfo}</p><a class="btn" href="${m.file}">${tr().more} →</a><a class="btn orange" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(tr().names[i]+' Павлодар')}">${lang==='ru'?'Найти на настоящей карте':'Нақты картадан іздеу'} ↗</a></div>`;
}
// РАХАТ — Вопросы викторины
function renderQuiz() {
  const host=document.getElementById('quiz-box');
  if(!host)return;
  if(quizIndex>=20) {
    host.innerHTML=`<h3>${quizScore}/20</h3><p>${tr().quiz}</p><button class="btn orange" id="restart">${tr().again}</button>`;
    document.getElementById('restart').onclick=()=>{quizIndex=0;quizScore=0;answered=false;renderQuiz();};
    return;
  }
  const source=tr().question[quizIndex];
  const shift=(quizIndex*3+1)%4;
  const order=[0,1,2,3].map(i=>(i+shift)%4);
  const q=[source[0],order.map(i=>source[1][i]),order.indexOf(source[2]),source[3]];
  host.innerHTML=`<div class="progress"><div style="width:${quizIndex*5}%"></div></div><p>${quizIndex+1} / 20</p><h3>${q[0]}</h3>${q[1].map((v,i)=>`<button class="answer" data-answer="${i}">${v}</button>`).join('')}<p id="feedback" aria-live="polite"></p><button class="btn orange" id="next" hidden>${tr().next} →</button>`;
  answered=false;
  host.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{
    if(answered)return;
    answered=true;
    const correct=Number(b.dataset.answer)===q[2];
    if(correct)quizScore++;
    host.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);
    host.querySelector('#feedback').textContent=(correct?'✓ ':'✕ ')+q[3];
    host.querySelector('#feedback').className=correct?'correct':'wrong';
    host.querySelector('#next').hidden=false;
  });
  host.querySelector('#next').onclick=()=>{quizIndex++;renderQuiz();};
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const modal=document.getElementById('modal');if(modal)modal.hidden=true;}});

