 const stops=[...root.querySelectorAll('section')].map(sec=>{const key=sec.classList.contains('famine-scrap')?'famine':sec.classList.contains('flame-scrap')?'flame':sec.classList.contains('heritage-notes')?'notes':sec.classList.contains('museum-knowledge')?'knowledge':sec.classList.contains('quote-section')?'quote':sec.classList.contains('oil-hero')?'home':sec.id||'gallery';return {el:sec,lines:lines[key]||lines.archive};});
 window.mountFloatingGuide(stops,()=>lang);
