// РАХАТ — Анимации сайта
function initArtEffects(){
  const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const targets=document.querySelectorAll('section .container, .card, .gallery button, .team-grid figure');
  if(!reduce && 'IntersectionObserver' in window){
    const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');observer.unobserve(e.target);}}),{threshold:.08});
    targets.forEach(el=>{el.classList.add('reveal');observer.observe(el);});
  }
  const hero=document.querySelector('.hero');
  if(hero&&!reduce){hero.addEventListener('pointermove',e=>{const r=hero.getBoundingClientRect();hero.style.setProperty('--mx',((e.clientX-r.left)/r.width-.5)*18+'px');hero.style.setProperty('--my',((e.clientY-r.top)/r.height-.5)*18+'px');},{passive:true});}
  document.querySelectorAll('.card').forEach(c=>c.addEventListener('pointermove',e=>{const r=c.getBoundingClientRect();c.style.setProperty('--glow-x',((e.clientX-r.left)/r.width*100)+'%');c.style.setProperty('--glow-y',((e.clientY-r.top)/r.height*100)+'%');},{passive:true}));
}
